sys_script_client.script:
function onSubmit() {

    // =====================================================
    // ROLE CHECK
    // =====================================================

    var isInterviewer = g_user.hasRole('x_snc_college_pl_0.interviewer');
    var isPlacementOfficer = g_user.hasRole('x_snc_college_pl_0.placement_officer');
	var isPlacementadmin = g_user.hasRole('x_snc_college_pl_0.placement_officer');
    var isStudent = g_user.hasRole('x_snc_college_pl_0.student_user');


    // Student cannot submit changes
    if (isStudent && !isInterviewer && !isPlacementOfficer && !isPlacementadmin) {
        return false;
    }


    // Only HR/Interviewer and Placement Officer
    if (!isInterviewer && !isPlacementOfficer &&!isPlacementadmin) {
        return false;
    }


    // =====================================================
    // GET VALUES
    // =====================================================

    var status = g_form.getValue('status');
    var result = g_form.getValue('result');
    var feedback = g_form.getValue('feedback');


    // =====================================================
    // COMPLETED VALIDATION
    // =====================================================

    if (status == 'completed') {

        if (result == '') {

            g_form.addErrorMessage(
                'Result is mandatory when Interview Status is Completed.'
            );

            g_form.setReadOnly('result', false);
            g_form.setReadOnly('feedback', false);

            return false;
        }


        if (feedback == '') {

            g_form.addErrorMessage(
                'Feedback is mandatory when Interview Status is Completed.'
            );

            g_form.setReadOnly('result', false);
            g_form.setReadOnly('feedback', false);

            return false;
        }
    }


    return true;
}
